"""Validate the dashboard and derive the public roadmap from one source of truth."""
import argparse
import datetime
import json
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'docs/dashboard'
LABELS = {'done': 'Fait', 'in_progress': 'En cours', 'planned': 'À faire', 'blocked': 'Bloqué'}


def render(data):
    datetime.date.fromisoformat(data['updated'])
    ids = set()
    milestones = {m['id'] for m in data['milestones']}
    lines = ['# Roadmap — moteur indépendant Rust + Bevy', '',
             '<!-- Generated by scripts/dashboard.py from docs/dashboard/data.json. -->', '',
             f"Mise à jour : {data['updated']}. **Fondations ; jeu non jouable.**", '',
             'Chaque tâche est un livrable vérifiable, pas une estimation de couverture du jeu.',
             'Le statut « fait » concerne son critère uniquement. Aucun calendrier de sortie promis.', '',
             f"Prochaine preuve : {data['next']}", '']
    for milestone in data['milestones']:
        assert all(dep in milestones for dep in milestone['depends_on']), 'Unknown milestone dependency'
        lines += [f"## {milestone['id']} — {milestone['title']}", '', milestone['goal'], '',
                  'Dépendances : ' + (', '.join(milestone['depends_on']) or 'aucune') + '.', '',
                  '| ID | Fonctionnalité | Statut | Critère d’acceptation |',
                  '| --- | --- | --- | --- |']
        for task in milestone['tasks']:
            assert task['id'] not in ids, 'Duplicate task ID'
            ids.add(task['id'])
            assert task['status'] in LABELS, 'Invalid task status'
            assert task['acceptance'].strip(), 'Missing acceptance criteria'
            cells = [task['id'], task['title'], LABELS[task['status']], task['acceptance']]
            lines.append('| ' + ' | '.join(c.replace('|', '\\|') for c in cells) + ' |')
        lines.append('')
    for capture in data['captures']:
        assert capture['kind'] == 'dashboard', 'Only dashboard screenshots are public at this stage'
        assert capture['source'] and capture['caption']
        datetime.date.fromisoformat(capture['date'])
        path = (SITE / capture['path']).resolve()
        assert path.is_relative_to((SITE / 'captures').resolve()), 'Capture must stay inside captures/'
        assert path.is_file(), f'Missing capture: {path}'
    for update in data['updates']:
        datetime.date.fromisoformat(update['date'])
        assert update['changes'] and update['validation'] and update['limits']
        if 'link' in update:
            assert update['link']['url'].startswith(data['repo'] + '/blob/main/'), 'Post link must target repository documentation'
    for name in ('style.css',):
        assert (SITE / name).is_file(), f'Missing dashboard asset {name}'
    lines += ['## Hors périmètre public', '',
              'Disques, BIOS, données extraites, code traduit du jeu, dumps et captures du jeu restent locaux.',
              'Voir [la méthode indépendante](docs/clean-room.md) et [les notices](NOTICE.md).', '']
    return '\n'.join(lines)


def blog(data):
    posts = []
    for update in data['updates']:
        changes = ''.join('<li>' + escape(change) + '</li>' for change in update['changes'])
        link = update.get('link')
        post_link = (f'<p class="reading"><a href="{escape(link["url"], quote=True)}">{escape(link["label"])}</a></p>' if link else '')
        posts.append(f'''<article>
  <time datetime="{escape(update['date'])}">{escape(update['date'])}</time>
  <h2>{escape(update['title'])}</h2>
  <p>{escape(update['summary'])}</p>
  <ul>{changes}</ul>
{post_link}
  <details><summary>Vérifications et limites</summary>
    <p>{escape(update['validation'])}</p><p>{escape(update['limits'])}</p>
  </details>
</article>''')
    captures = ''.join(
        f'<li><a href="{escape(c["path"], quote=True)}">{escape(c["caption"])}</a>'
        f' <small>— {escape(c["date"])} · {escape(c["source"])}</small></li>'
        for c in data['captures'])
    capture_section = f'<section><h2>Captures du carnet</h2><ul>{captures}</ul></section>' if captures else ''
    return f'''<!doctype html>
<html lang="fr">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="Notes de développement d’un moteur indépendant pour God Hand, en Rust et Bevy. Projet au tout début.">
  <title>God Hand PC — carnet de développement</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
<header>
  <a class="site-name" href="./">God Hand PC</a>
  <nav aria-label="Navigation"><a href="#journal">Journal</a><a href="{escape(data['repo'])}/blob/main/ROADMAP.md">Roadmap</a><a href="{escape(data['repo'])}">Code</a></nav>
</header>
<main>
  <section class="about">
    <h1>Carnet de développement</h1>
    <p>Ce projet explore une réimplémentation indépendante du moteur de God Hand
    en Rust et Bevy. Le code est ouvert ; les données du jeu devront venir de
    l’ISO personnelle de chaque utilisateur.</p>
    <p>On en est au début. Le jeu n’est pas jouable dans ce moteur. Cette page
    rassemble les choix techniques, les petites avancées et ce qui reste à comprendre.</p>
  </section>
  <section id="journal" aria-label="Entrées du journal">
    {''.join(posts)}
  </section>
  {capture_section}
  <section class="reading">
    <h2>Pour situer le projet</h2>
    <p><a href="{escape(data['repo'])}/blob/main/docs/research-2026-11-03.md">Notes sur les projets de recompilation PS2</a><br>
    <a href="{escape(data['repo'])}/blob/main/docs/clean-room.md">Méthode d’implémentation indépendante</a><br>
    <a href="{escape(data['repo'])}/blob/main/ROADMAP.md">Liste des fonctionnalités envisagées</a></p>
  </section>
</main>
<footer>Projet indépendant, sans affiliation avec les ayants droit.<br>
Code original sous MIT · Hébergé sur GitHub Pages (offre gratuite).</footer>
</body>
</html>
'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    data = json.loads((SITE / 'data.json').read_text(encoding='utf-8'))
    content = render(data)
    outputs = {ROOT / 'ROADMAP.md': content, SITE / 'index.html': blog(data)}
    if args.check:
        for destination, expected in outputs.items():
            assert destination.read_text(encoding='utf-8') == expected, f'{destination.name} stale: run python scripts/dashboard.py'
        print('Blog data, captures, HTML and roadmap: valid.')
    else:
        for destination, expected in outputs.items():
            destination.write_text(expected, encoding='utf-8', newline='\n')
        print('ROADMAP.md and blog HTML updated.')


if __name__ == '__main__':
    main()
